"use strict";

const https = require("https");
const http = require("http");
const tls = require("tls");
const zlib = require("zlib");

const UA =
  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36";

const MOBILE_UA =
  "Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Mobile Safari/537.36";

function firstProxy(proxy) {
  if (!proxy) return null;
  const list = (Array.isArray(proxy) ? proxy : [proxy]).map(String).filter(Boolean);
  return list.length ? list[0] : null;
}

function connectViaProxy(proxyUrl, targetHost) {
  return new Promise((resolveP, rejectP) => {
    let parsed;
    try {
      parsed = new URL(String(proxyUrl));
    } catch (e) {
      rejectP(new Error("Invalid proxy URL"));
      return;
    }
    if (parsed.protocol !== "http:") {
      rejectP(new Error("Search proxy must use an http:// URL"));
      return;
    }
    const connectHeaders = { Host: targetHost + ":443" };
    if (parsed.username) {
      connectHeaders["Proxy-Authorization"] =
        "Basic " +
        Buffer.from(decodeURIComponent(parsed.username) + ":" + decodeURIComponent(parsed.password || "")).toString("base64");
    }
    const creq = http.request({
      host: parsed.hostname,
      port: parsed.port ? parseInt(parsed.port, 10) : 80,
      method: "CONNECT",
      path: targetHost + ":443",
      headers: connectHeaders,
      timeout: 30000,
    });
    creq.on("connect", (cres, socket) => {
      if (cres.statusCode !== 200) {
        socket.destroy();
        rejectP(new Error("Proxy CONNECT failed: HTTP " + cres.statusCode));
        return;
      }
      const tlsSocket = tls.connect({ socket: socket, servername: targetHost }, () => resolveP(tlsSocket));
      tlsSocket.on("error", rejectP);
    });
    creq.on("timeout", () => creq.destroy(new Error("Proxy CONNECT timed out")));
    creq.on("error", rejectP);
    creq.end();
  });
}

function request(url, options) {
  const opts = options || {};
  return new Promise((resolveP, rejectP) => {
    let settled = false;
    const resolve = (v) => {
      if (settled) return;
      settled = true;
      clearTimeout(hardTimer);
      resolveP(v);
    };
    const reject = (e) => {
      if (settled) return;
      settled = true;
      clearTimeout(hardTimer);
      rejectP(e);
    };
    const hardTimer = setTimeout(() => {
      reject(new Error("Request timed out"));
    }, 40000);
    const u = new URL(url);
    const body = opts.body || null;
    const headers = Object.assign(
      {
        "user-agent": opts.ua || UA,
        "accept-language": "en-US,en;q=0.9",
        "accept-encoding": "gzip, deflate, br",
      },
      opts.headers || {}
    );
    if (body) {
      headers["content-length"] = Buffer.byteLength(body);
    }
    const run = async () => {
      let tunnel = null;
      const proxy = firstProxy(opts.proxy);
      if (proxy) tunnel = await connectViaProxy(proxy, u.hostname);
      const reqOpts = {
        hostname: u.hostname,
        path: u.pathname + u.search,
        method: opts.method || "GET",
        headers: headers,
        timeout: 30000,
      };
      if (tunnel) reqOpts.createConnection = () => tunnel;
      const req = https.request(
        reqOpts,
      (res) => {
        if (
          res.statusCode >= 300 &&
          res.statusCode < 400 &&
          res.headers.location &&
          opts.followRedirects !== false
        ) {
          res.resume();
          resolve(
            request(res.headers.location, Object.assign({}, opts, { method: "GET", body: null }))
          );
          return;
        }
        const chunks = [];
        let stream = res;
        const enc = (res.headers["content-encoding"] || "").toLowerCase();
        if (enc === "gzip") stream = res.pipe(zlib.createGunzip());
        else if (enc === "deflate") stream = res.pipe(zlib.createInflate());
        else if (enc === "br") stream = res.pipe(zlib.createBrotliDecompress());
        stream.on("data", (c) => chunks.push(c));
        stream.on("end", () =>
          resolve({
            status: res.statusCode,
            headers: res.headers,
            body: Buffer.concat(chunks).toString("utf8"),
          })
        );
        stream.on("error", reject);
      }
    );
      req.on("timeout", () => req.destroy(new Error("Request timed out")));
      req.on("error", reject);
      if (body) req.write(body);
      req.end();
    };
    run().catch(reject);
  });
}

function extractInitialData(html) {
  let m = html.match(/var ytInitialData = (\{.+?\});<\/script>/s);
  if (!m) m = html.match(/ytInitialData"\]\s*=\s*(\{.+?\});/s);
  if (!m) m = html.match(/window\["ytInitialData"\]\s*=\s*(\{.+?\});/s);
  if (!m) return null;
  try {
    return JSON.parse(m[1]);
  } catch (e) {
    return null;
  }
}

function runsText(node) {
  if (!node) return null;
  if (typeof node.simpleText === "string") return node.simpleText;
  if (Array.isArray(node.runs)) {
    return node.runs.map((r) => r.text || "").join("");
  }
  return null;
}

function collectRenderers(node, out) {
  if (!node || typeof node !== "object") return;
  if (node.videoRenderer && node.videoRenderer.videoId) {
    out.push(node.videoRenderer);
  }
  const keys = Object.keys(node);
  for (let i = 0; i < keys.length; i++) {
    collectRenderers(node[keys[i]], out);
  }
}

function mapVideo(v) {
  const thumbs = (v.thumbnail && v.thumbnail.thumbnails) || [];
  const thumb = thumbs.length ? thumbs[thumbs.length - 1].url : null;
  return {
    id: v.videoId,
    title: runsText(v.title),
    url: "https://www.youtube.com/watch?v=" + v.videoId,
    author: runsText(v.ownerText) || runsText(v.longBylineText) || runsText(v.shortBylineText),
    duration: v.lengthText ? runsText(v.lengthText) : null,
    thumbnail: thumb,
    views: runsText(v.viewCountText),
  };
}

async function fetchYouTubeResults(query, ua, proxy) {
  const url =
    "https://www.youtube.com/results?search_query=" + encodeURIComponent(query) + "&hl=en&gl=US";
  const res = await request(url, {
    ua: ua,
    proxy: proxy,
    headers: {
      accept:
        "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8",
      cookie: "CONSENT=YES+cb.20210328-17-p0.en+FX+299; SOCS=CAI",
    },
  });
  if (res.status !== 200) {
    throw new Error("YouTube Search Error: HTTP " + res.status);
  }
  const data = extractInitialData(res.body);
  if (!data) {
    throw new Error("YouTube Search Error: could not parse ytInitialData from results page");
  }
  const renderers = [];
  collectRenderers(data, renderers);
  return renderers;
}

async function searchYouTube(query, limit, proxy) {
  const max = limit || 10;
  if (!query || typeof query !== "string") {
    throw new Error("YouTube Search Error: query is required");
  }
  let renderers;
  try {
    renderers = await fetchYouTubeResults(query, UA, proxy);
  } catch (e) {
    renderers = await fetchYouTubeResults(query, MOBILE_UA, proxy);
  }
  if (!renderers.length) {
    try {
      const retry = await fetchYouTubeResults(query, MOBILE_UA, proxy);
      if (retry.length) renderers = retry;
    } catch (e2) {}
  }
  if (!renderers.length) {
    throw new Error("YouTube Search Error: no video results found for query");
  }
  const seen = {};
  const out = [];
  for (let i = 0; i < renderers.length && out.length < max; i++) {
    const item = mapVideo(renderers[i]);
    if (!item.id || seen[item.id]) continue;
    seen[item.id] = true;
    out.push(item);
  }
  return out;
}

async function searchTikTok(query, limit, proxy) {
  const max = limit || 10;
  if (!query || typeof query !== "string") {
    throw new Error("TikTok Search Error: query is required");
  }
  const form =
    "keywords=" +
    encodeURIComponent(query) +
    "&count=" +
    encodeURIComponent(String(max)) +
    "&cursor=0&HD=1";
  let res;
  try {
    res = await request("https://www.tikwm.com/api/feed/search", {
      method: "POST",
      body: form,
      proxy: proxy,
      headers: {
        "content-type": "application/x-www-form-urlencoded",
        accept: "application/json",
        origin: "https://www.tikwm.com",
        referer: "https://www.tikwm.com/",
      },
    });
  } catch (e) {
    throw new Error("TikTok Search Error: " + e.message);
  }
  if (res.status !== 200) {
    const blocked =
      res.body && res.body.indexOf("Just a moment") !== -1
        ? " (Cloudflare challenge — this IP is blocked by tikwm)"
        : "";
    throw new Error("TikTok Search Error: HTTP " + res.status + blocked);
  }
  let data;
  try {
    data = JSON.parse(res.body);
  } catch (e) {
    throw new Error("TikTok Search Error: invalid JSON response");
  }
  const videos = data && data.data && Array.isArray(data.data.videos) ? data.data.videos : null;
  if (!videos) {
    const msg = (data && (data.msg || data.message)) || "unexpected response shape";
    throw new Error("TikTok Search Error: " + msg);
  }
  const out = [];
  for (let i = 0; i < videos.length && out.length < max; i++) {
    const v = videos[i];
    const authorObj = v.author || {};
    const uniqueId = authorObj.unique_id || authorObj.uniqueId || null;
    const authorName = uniqueId || authorObj.nickname || null;
    out.push({
      id: v.video_id || v.id,
      title: v.title || null,
      url:
        uniqueId && (v.video_id || v.id)
          ? "https://www.tiktok.com/@" + uniqueId + "/video/" + (v.video_id || v.id)
          : null,
      author: authorName,
      duration: typeof v.duration === "number" ? v.duration : null,
      thumbnail: v.cover || v.origin_cover || null,
      views: typeof v.play_count === "number" ? v.play_count : null,
    });
  }
  if (!out.length) {
    throw new Error("TikTok Search Error: no results found for query");
  }
  return out;
}

module.exports = { searchYouTube, searchTikTok };
